1	using System.Collections.Generic;
2	using Chaos.AnimatorExtensions;
3	using UnityEngine;
4	
5	public class Archer : Enemy
6	{
7		public class NeutralArcherDoubleState : ArcherAttackSkillState
8		{
9			public NeutralArcherDoubleState(string newName, FSM newFSM, Archer newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD)
10				: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD)
11			{
12			}
13	
14			public override void OnEnter()
15			{
16				base.OnEnter();
17				parent.enemySkillUseInProgress = true;
18				flashThreshold = 0f;
19				chargeTime = 0f;
20				chargeDelay = StdWindupTime * 1.25f;
21				attackDelay = StdExitTime * 1.5f;
22				chargeStopwatchID = ChaosStopwatch.Begin(chargeTime);
23				chargeDelayStopwatchID = ChaosStopwatch.Begin(chargeTime + chargeDelay);
24				attackDelayStopwatchID = ChaosStopwatch.Begin(chargeTime + chargeDelay + attackDelay);
25				AimTowardsTarget();
26			}
27	
28			public override void HoldProjectile()
29			{
30				if (!(currentProjectile == null))
31				{
32					base.HoldProjectile();
33					FlashTargetLine(ChaosStopwatch.GetTimePercentage(chargeDelayStopwatchID));
34				}
35			}
36	
37			public override Projectile CreateProjectile()
38			{
39				base.CreateProjectile();
40				currentProjectile.attackBox.SetAttackInfo(parent.skillCategory, parent.doubleSkillID);
41				return currentProjectile;
42			}
43	
44			public override void SetVars()
45			{
46				projectilePrefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/BaseArrow.prefab");
47				shootAudioID = "ArcherArrow";
48			}
49	
50			public override void SetReleaseVars()
51			{
52				currentProjectile.moveSpeed = 28f;
53				currentProjectile.flyTime = 0.5f;
54				currentProjectile.RefreshFlightTime();
55				currentProjectile.goThroughWalls = false;
56			}
57		}
58	
59		public class NeutralArcherAttackState : ArcherAttackSkillState
60		{
61			private bool useDouble;
62	
63			public NeutralArcherAttackState(string newName, FSM newFSM, Archer newEnt)
64				: base(newName, newFSM, newEnt)
65			{
66			}
67	
68			public override void OnEnter()
69			{
70				base.OnEnter();
71				useDouble = parent.CanUseSkills && parent.doubleState.IsReady();
72				if (useDouble)
73				{
74					ChaosStopwatch.Stop(attackDelayStopwatchID);
75				}
76			}
77	
78			public override void ExitTransition()
79			{
80				if (useDouble && parent.UpdateTargetInfo(-1f, reqLOS: true) != null)
81				{
82					fsm.ChangeState(parent.doubleState.name);
83				}
84				else
85				{
86					base.ExitTransition();
87				}
88			}
89	
90			public override void SetVars()
91			{
92				projectilePrefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/BaseArrow.prefab");
93				shootAudioID = "ArcherArrow";
94			}
95	
96			public override void SetReleaseVars()
97			{
98				currentProjectile.moveSpeed = 28f;
99				currentProjectile.flyTime = 0.5f;
100				currentProjectile.RefreshFlightTime();
101				currentProjectile.goThroughWalls = false;
102			}
103		}
104	
105		public class ArcherAttackSkillState : SkillState
106		{
107			public GameObject projectilePrefab;
108	
109			public Projectile currentProjectile;
110	
111			public bool projectileCreated;
112	
113			public bool projectileReleased;
114	
115			public Vector3 aimVector;
116	
117			public Vector3 armVector;
118	
119			public float attackRangeModifier = 2f;
120	
121			public int chargeStopwatchID;
122	
123			public float chargeTime = 1f;
124	
125			public float chargeDelay;
126	
127			public int chargeDelayStopwatchID;
128	
129			public float attackDelay;
130	
131			public int attackDelayStopwatchID;
132	
133			public Color lineColor;
134	
135			public Color lineColorRed;
136	
137			public Color lineColorFlash;
138	
139			public float lineWidth;
140	
141			public float targetLineMaxWidth = 7f;
142	
143			public float targetLineMaxOpacity = 0.6f;
144	
145			public float targetLineRange = -1f;
146	
147			public bool lineLocked;
148	
149			public bool drawSoundPlayed;
150	
151			public string shootAudioID = string.Empty;
152	
153			public bool shootAnimComplete;
154	
155			public float flashThreshold = 0.8f;
156	
157			public float flashTime = 0.025f;
158	
159			private bool flashRed = true;
160	
161			private ChaosQuickStopwatch flashTimer;
162	
163			private AudioSource windupAudio;
164	
165			private TargetInfo lockedTargetInfo;
166	
167			public new Archer parent;
168	
169			public ArcherAttackSkillState(string newName, FSM newFSM, Archer newParent, int newReq = 0, int newPriority = 0, float newMin = 0f, float newMax = 0f, float newCD = 0f, bool autoUse = false)
170				: base(newName, newFSM, newParent, newReq, newPriority, newMin, newMax, newCD, autoUse)
171			{
172				parent = newParent;
173				lineColorRed = new Color(0.8f, 0f, 0f, 0f);
174				lineColorFlash = new Color(1f, 1f, 1f, 0.75f);
175				lineColor = lineColorRed;
176				targetLineRange = parent.targetLine.maxRange;
177				SetVars();
178				usePowerUpEffect = false;
179			}
180	
181			public virtual void SetVars()
182			{
183			}
184	
185			public virtual Vector3 AimTowardsTarget(bool updateAimVector = true, bool updateTargetLine = true, bool updateTargetLineWidth = true)
186			{
187				if (updateAimVector && parent.closestTargetInfo != null && parent.closestTargetInfo.transform != null && parent.closestTargetInfo.hurtBoxTransform != null)
188				{
189					parent.FaceTarget(parent.closestTargetInfo.transform.position, parent.animFacingDirections);
190					aimVector = (parent.closestTargetInfo.hurtBoxTransform.position - parent.bowArm.transform.position).normalized;
191					armVector = Globals.GetRotationVector(aimVector);
192					if (!parent.isFacingRight)
193					{
194						armVector.z *= -1f;
195					}
196					armVector.z += 90f;
197					parent.bowArm.localEulerAngles = armVector;
198				}
199				if (updateTargetLine)
200				{
201					parent.targetLine.aimVector = aimVector;
202					FlashTargetLine(ChaosStopwatch.GetTimePercentage(chargeStopwatchID));
203				}
204				HoldProjectile();
205				return aimVector;
206			}
207	
208			public virtual void FlashTargetLine(float givenValue)
209			{
210				if (givenValue >= flashThreshold)
211				{
212					if (flashTimer == null)
213					{
214						flashTimer = new ChaosQuickStopwatch(flashTime);
215						flashTimer.IsRunning = true;
216						lineColor.a = 1f;
217					}
218					else if (!flashTimer.IsRunning)
219					{
220						if (flashRed)
221						{
222							lineColor = lineColorRed;
223							lineColor.a = 1f;
224							flashRed = false;
225						}
226						else
227						{
228							flashRed = true;
229							lineColor = lineColorFlash;
230						}
231						flashTimer.IsRunning = true;
232					}
233				}
234				else
235				{
236					lineColor.a = targetLineMaxOpacity * givenValue;
237				}
238				parent.targetLine.line.SetColors(lineColor, lineColor);
