63				parent.alerted = true;
64				parent.anim.PlayDirectional("Run" + parent.facingDirection);
65				calculatedAvoidance = Random.Range(0f, 1f);
66				deviatePath = false;
67				chaseStopwatchID = ChaosStopwatch.Begin(maxChaseTime);
68			}
69	
70			public override void Update()
71			{
72				parent.closestTargetInfo = Entity.GetClosestTarget(parent.targetGroup, parent.transform.position, parent.escapeRadius, parent.onlyTargetPlayers);
73				if (parent.closestTargetInfo == null || parent.closestTargetInfo.hurtBoxTransform == null)
74				{
75					fsm.ChangeState("GoBack");
76				}
77				else
78				{
79					if (parent.HandleExtraSkills())
80					{
81						return;
82					}
83					if (Vector2.Distance(parent.closestTargetInfo.position, parent.transform.position) < parent.alertRadius && Entity.HasLineOfSight(parent.transform.position, parent.closestTargetInfo.transform.position, parent.maxAlertDistance, parent.lineOfSightLayerMask))
84					{
85						parent.requestPathStopwatchID = -1;
86						Physics2D.OverlapCircleNonAlloc(parent.transform.position, parent.alertRadius * 0.5f, projectileCheck);
87						for (int i = 0; i < projectileCheck.Length; i++)
88						{
89							if (!(projectileCheck[i] != null) || !(projectileCheck[i].transform.parent != null))
90							{
91								continue;
92							}
93							otherProjectile = projectileCheck[i].transform.parent.gameObject.GetComponent<Projectile>();
94							if (otherProjectile != null && otherProjectile.attackBox.atkInfo.skillCategory.Contains("Player"))
95							{
96								if (parent.tornadoReady)
97								{
98									fsm.ChangeState("Tornado");
99									return;
100								}
101								if (parent.dashAvailable && parent.CalculateDashVector(dashingTowards: false, otherProjectile.transform))
102								{
103									fsm.ChangeState("Dash");
104									return;
105								}
106							}
107						}
108						if (!deviatePath)
109						{
110							parent.PlayAnimOnFaceDirChange("Run", parent.closestTargetInfo.position);
111						}
112						distanceToTarget = parent.closestTargetInfo.distance;
113						if (distanceToTarget < parent.useTornadoRange && parent.tornadoReady)
114						{
115							fsm.ChangeState("Tornado");
116							return;
117						}
118						if (distanceToTarget < parent.useFireBallMaxRange && parent.fireballReady)
119						{
120							fsm.ChangeState("Fireball");
121							return;
122						}
123						if (distanceToTarget > parent.useSwordThrowMinRange && distanceToTarget < parent.useSwordThrowMaxRange && parent.swordThrowReady)
124						{
125							fsm.ChangeState("SwordThrow");
126							return;
127						}
128						if (distanceToTarget > 2f * parent.attackRadius && parent.dashAvailable)
129						{
130							avoid = calculatedAvoidance > avoidPercentage;
131							if (parent.CalculateDashVector(avoid))
132							{
133								fsm.ChangeState("Dash");
134								return;
135							}
136						}
137						if (deviatePath)
138						{
139							if (!ChaosStopwatch.Check(deviateStopwatchID))
140							{
141								deviationDirection = parent.transform.position + (Vector3)deviationOffset;
142								parent.PlayAnimOnFaceDirChange("Run", deviationDirection);
143								parent.movement.MoveToTarget(deviationDirection);
144								return;
145							}
146							deviatePath = false;
147							chaseStopwatchID = ChaosStopwatch.Begin(maxChaseTime);
148						}
149						if (!parent.movement.MoveToTarget(parent.closestTargetInfo.transform.position, parent.attackRadius))
150						{
151							if (ChaosStopwatch.Check(chaseStopwatchID))
152							{
153								deviatePath = true;
154								deviateStopwatchID = ChaosStopwatch.Begin(deviateTime);
155								deviationOffset = new Vector2(Random.Range(-1, 2), Random.Range(-1, 2));
156								parent.movement.EndMovement();
157							}
158						}
159						else
160						{
161							fsm.ChangeState("Attack");
162						}
163					}
164					else if (parent.DashOverPits())
165					{
166						parent.requestPathStopwatchID = -1;
167					}
168					else if (ChaosStopwatch.Check(parent.requestPathStopwatchID))
169					{
170						parent.requestPathStopwatchID = ChaosStopwatch.Begin(parent.requestPathTime);
171						parent.followingPath = false;
172						if (parent.FindAndTraversePath(parent.traversableNodeMap, parent.transform.position, parent.closestTargetInfo.position, parent.minNodeDist, "Run", appendFacingDirection: true, parent.animFacingDirections) == -1)
173						{
174							fsm.ChangeState("GoBack");
175						}
176						else
177						{
178							parent.followingPath = true;
179						}
180					}
181					else if (parent.followingPath && parent.FindAndTraversePath(parent.traversableNodeMap, parent.transform.position, parent.closestTargetInfo.position, parent.minNodeDist, "Run", appendFacingDirection: true, parent.animFacingDirections) != 0)
182					{
183						parent.followingPath = false;
184						parent.HandleExitTransitions();
185					}
186				}
187			}
188		}
