804		private bool CalculateDashVector(bool dashingTowards = true, Transform targetTransform = null)
805		{
806			Vector2 vector = new Vector2(Random.Range(-1f, 1f), Random.Range(-0.75f, 0.75f));
807			Transform transform;
808			if (targetTransform == null)
809			{
810				if (closestTargetInfo == null || !(closestTargetInfo.transform != null))
811				{
812					movement.dashVector = vector;
813					return true;
814				}
815				transform = closestTargetInfo.transform;
816			}
817			else
818			{
819				transform = targetTransform;
820			}
821			if (dashingTowards)
822			{
823				movement.dashVector = (transform.position - base.transform.position + (Vector3)vector).normalized;
824			}
825			else
826			{
827				movement.dashVector = (base.transform.position - transform.position + (Vector3)vector).normalized;
828			}
829			return Entity.HasLineOfSight(movement.dashVector * 4.8f + (Vector2)base.transform.position, movement.dashVector * 6.3f + (Vector2)base.transform.position, 8f, ChaosCollisions.layerPit);
