135						SoundManager.PlayAudioWithDistance("MageFireballForm", parent.transform.position);
136						break;
137					}
138					case StopwatchState.Done:
139						parent.fsm.ChangeState(fsm.defaultStateName);
140						break;
141					}
142				}
143			}
