100			public override void Update()
101			{
102				if (!projectileCreated)
103				{
104					parent.UpdateTargetInfo(parent.attackRadius * attackRangeModifier);
105					if (parent.closestTargetInfo == null)
106					{
107						ExitTransition();
108						return;
109					}
110					AimTowardsTarget();
111					parent.anim.Play("AttackWindup", -1, (float)projectileCounter / (float)projectileCount);
112					if (!parent.HandleExtraSkills(hasLOS: true, updateTarget: true, updateLOS: true))
113					{
114						switch (ChaosStopwatch.CheckInterval(projectileSpawnStopwatchID))
115						{
116						case StopwatchState.Ready:
117							projectileList.Add(CreateIceShard());
118							projectileCounter++;
119							break;
120						case StopwatchState.Done:
121							projectileCreated = true;
122							chargeDelayStopwatchID = ChaosStopwatch.Begin(chargeDelay);
123							projectileReleaseStopwatchID = ChaosStopwatch.Begin(chargeDelay + projectileReleaseDelay, useInterval: true, projectileReleaseDelay, projectileCount);
124							break;
125						}
126						if (!drawSoundPlayed && ChaosStopwatch.GetTimePercentage(chargeStopwatchID) > 0.25f)
127						{
128							drawSoundPlayed = true;
129							SoundManager.PlayAudioWithDistance("ArcherAttackWindup", parent.transform.position);
130						}
131					}
132				}
133				else if (!projectileReleased)
134				{
135					if (!ChaosStopwatch.Check(chargeDelayStopwatchID))
136					{
137						AimTowardsTarget();
138						return;
139					}
140					switch (ChaosStopwatch.CheckInterval(projectileReleaseStopwatchID))
141					{
142					case StopwatchState.Running:
143						break;
144					case StopwatchState.Ready:
145						parent.targetLine.IsVisible(status: false);
146						parent.anim.Play("AttackRelease", -1, 0.4f);
147						ReleaseProjectile();
148						break;
149					case StopwatchState.Done:
150						projectileReleased = true;
151						attackDelayStopwatchID = ChaosStopwatch.Begin(attackDelay);
152						break;
153					}
154				}
155				else
156				{
157					HandleAttackExit();
158				}
159			}
