168					for (int i = 0; i < projectileList.Count; i++)
169					{
170						currentIS = projectileList[i];
171						if (currentIS != null)
172						{
173							currentIS.transform.SetParent(null);
174							Object.Destroy(currentIS.gameObject);
175						}
176					}
177				}
178				projectileList.Clear();
179				projectilePositionDict.Clear();
180			}
181		}
